mapper.select:
SELECT , st.store_name AS storeName, eu.nickname AS userName
w.is_deleted = 0
AND (w.warehouse_name LIKE CONCAT('%', #{q.keyword}, '%') OR w.warehouse_code LIKE CONCAT('%', #{q.keyword}, '%') OR w.contact_name LIKE CONCAT('%', #{q.keyword}, '%') OR w.contact_phone LIKE CONCAT('%', #{q.keyword}, '%'))
AND w.warehouse_type = #{q.warehouseType}
AND w.status = #{q.status}
AND w.user_id = #{q.userId}
AND w.store_id = #{q.storeId}
ORDER BY FIELD(w.status, 1, 2, 3, 0), w.id DESC
